// Exponential backoff + jitter for signaling/join attempts (browser-side)
async function joinMeeting(signalingUrl, maxAttempts = 6) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const resp = await fetch(signalingUrl, { method: 'POST', body: JSON.stringify({ action: 'join' }) });
      if (!resp.ok) throw new Error('signaling failure');
      return await resp.json(); // success: signaling assigned SFU/TURN
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      // exponential backoff with full jitter
      const base = Math.min(1000 * Math.pow(2, attempt), 30000); // cap at 30s
      const jitter = Math.random() * base;
      await new Promise(r => setTimeout(r, jitter));
    }
  }
}
